function saveStatus(status,time){$('save-status').hidden=!accounts.user;$('save-status').dataset.state=status;const texts={loading:'Загрузка…',saving:'Сохраняется…',saved:'Сохранено',ready:'Автосохранение',offline:'Нет связи · повторить',conflict:'Другая сессия',session:'Нужен вход',invalid:'Ошибка сохранения','restored-other':'Новая сессия'};$('save-text').textContent=texts[status]??status;$('raid-save').textContent=texts[status]??status;$('save-status').title=time?`Сохранено ${new Date(time).toLocaleTimeString('ru-RU')}`:'Нажми, чтобы повторить сохранение';if(status==='restored-other')toast('Загружено более новое сохранение из другой сессии.',5000);if(['conflict','session','invalid'].includes(status)){$('sync-block').hidden=false;$('sync-message').textContent=status==='conflict'?'Прогресс изменён в другой вкладке или на другом устройстве. Загрузи последнее сохранение.':status==='session'?'Сессия входа закончилась. Войди снова, чтобы сохранить прогресс.':'Не удалось проверить сохранение. Прогресс остаётся в открытой игре. Попробуй сохранить ещё раз.';$('sync-server').hidden=status!=='conflict';$('sync-retry').hidden=status==='conflict';}}
function snapshot(){return {version:5,regions,state:{...state,party:state.party.map(p=>({...p})),stones:{...state.stones},seen:[...state.seen],caught:[...state.caught],pickedStones:[...state.pickedStones],visited:[...state.visited]},world:world.snapshotWorld(),battle:battle&&!battle.resolved?{wildKey:battle.wild.key,enemy:{...battle.enemy},ownUid:battle.own.uid,turn:battle.turn,specialCooldown:battle.specialCooldown}:null,raid:raid&&!raid.resolved?{uids:[...raid.uids],bossHp:raid.bossHp,turn:raid.turn,cooldowns:[...raid.cooldowns]}:null,settings:{soundEnabled}};}
function saveGame(){if(state.started&&!applyingSave&&saves.ready)saves.enqueue(snapshot());}
async function loadAccountProgress(){if(!accounts.user)return;if(state.started&&accounts.user.id===saves.accountKey){saves.blocked=false;$('sync-block').hidden=true;await saves.flushAll();return;}if(state.started){location.reload();return;}progressLoading=true;try{loadedSnapshot=await saves.load();$('sync-block').hidden=true;showStartState();}catch(error){$('sync-block').hidden=false;$('sync-message').textContent='Не удалось загрузить твоё сохранение. Проверь интернет и нажми «Повторить». Начинать заново не нужно.';$('sync-server').hidden=true;$('sync-retry').hidden=false;}finally{progressLoading=false;}}
function showStartState(){if(!world?.models.size)return;const old=loadedSnapshot?.state;if(old){const p=old.party[old.active];world.setHero(p.species);$('hero-name').textContent=SPECIES[p.species].name;$('hero-type').innerHTML=typePill(p.species);$('hero-desc').textContent=`Уровень ${p.level} · ${rarity(p.species)}`;document.querySelector('.start-heading h1').innerHTML='С возвращением,<br>тренер!';document.querySelector('.start-heading p').textContent='Твоя команда ждёт. Продолжим исследовать острова?';$('starter-grid').hidden=true;$('continue-summary').hidden=false;$('continue-summary').textContent=`Покемонов в команде: ${old.party.length} · Открыто форм: ${old.caught.length}/${ALL_IDS.length} · Побед: ${old.wins}`;document.querySelector('.dock-heading>span').textContent='ПРИКЛЮЧЕНИЕ СОХРАНЕНО';$('begin').innerHTML=`Продолжить приключение ${icon('arrow')}`;}else{selectStarter(STARTER_ID);$('begin').innerHTML=`${accounts.user?'Начать с Пикачу':'Войти и начать'} ${icon('arrow')}`;}}
function toast(message,time=3400){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,time);}
function sound(kind='tap'){if(!soundEnabled)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const melodies={tap:[520],step:[170],hit:[220,130],win:[440,550,660,880],catch:[650,780,980],evolve:[330,440,550,660,880],fail:[300,190],pickup:[660,880]};const notes=melodies[kind]||melodies.tap;notes.forEach((frequency,i)=>{const t=audioContext.currentTime+i*.09,osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type=kind==='hit'?'triangle':'sine';osc.frequency.setValueAtTime(frequency,t);gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(.075,t+.009);gain.gain.exponentialRampToValueAtTime(.001,t+.17);osc.connect(gain);gain.connect(audioContext.destination);osc.start(t);osc.stop(t+.18);});}catch{soundEnabled=false;}}
function active(){return state.party[state.active];}
function percent(a,b){return `${Math.max(0,Math.min(100,a/b*100))}%`;}
function portrait(id){return world.portraits[id];}
function selectStarter(id){if(id!==STARTER_ID||state.started||loadedSnapshot)return;chosen=id;world.setHero(id);$('hero-name').textContent=SPECIES[id].name;$('hero-type').innerHTML=`${icon(TYPES[SPECIES[id].type].icon)} ${TYPES[SPECIES[id].type].name}`;$('hero-type').style.setProperty('--type-color',TYPES[SPECIES[id].type].color);$('hero-desc').textContent=descriptions[id];document.querySelectorAll('.starter-card').forEach(el=>{el.classList.toggle('active',Number(el.dataset.id)===id);el.setAttribute('aria-pressed',String(Number(el.dataset.id)===id));});if(innerWidth<700&& !$('start').hidden)document.querySelector('.starter-card.active')?.scrollIntoView({block:'nearest',inline:'center',behavior:'smooth'});sound();}
function startGame(){if(state.started||!world.models.has(STARTER_ID))return;if(!accounts.user){accounts.open();return;}if(progressLoading||!saves.ready){loadAccountProgress();return;}applyingSave=true;
 if(loadedSnapshot){const data=loadedSnapshot;Object.assign(state,data.state);regions=data.regions??{};world.bossDefeated=state.bossDefeated;world.configureIsland(state.island);for(const key of ['seen','caught','pickedStones','visited'])state[key]=new Set(data.state[key]);reserveUids([...state.party,...(data.battle?[data.battle.enemy]:[])]);world.restoreWorld(data.world);soundEnabled=data.settings.soundEnabled;world.begin(active().species);if(data.battle){const b=data.battle;battle={wild:world.wild[b.wildKey],enemy:{...b.enemy},own:active(),turn:b.turn,specialCooldown:b.specialCooldown};world.beginBattle(active().species,b.enemy.species);$('battle-ui').hidden=false;lock=false;updateBattle();battleMessage('Встреча восстановлена. Твой ход.');}if(data.raid){raid={...data.raid,uids:[...data.raid.uids],cooldowns:[...data.raid.cooldowns]};mountRaid();}loadedSnapshot=null;
 }else{state.started=true;state.party.push(newPokemon(STARTER_ID,5));state.caught.add(STARTER_ID);state.seen.add(STARTER_ID);world.begin(STARTER_ID);}
 $('start').hidden=true;$('hud').hidden=!!battle||!!raid;$('sound').setAttribute('aria-pressed',String(soundEnabled));$('sound').querySelector('.sound-off').hidden=soundEnabled;applyingSave=false;updateHUD();sound('win');toast(battle||raid?'Бой восстановлен с последнего завершённого хода.':'Команда и прогресс сохраняются автоматически.',5000);if(state.finalDefeated&&!state.finalCreditsSeen&&!raid)showCredits();
}

